"""Original Vietnamese business story; every example value is fictional."""
import json
from pathlib import Path
root=Path(__file__).resolve().parent
chapters=[]
def chapter(cid,title):
    c={'id':cid,'title':title,'beats':[]};chapters.append(c);return c
def beat(c,bid,text,layout='b-photo',headline='',tag='cafe',**design):
    c['beats'].append({'id':bid,'text':text,'phase':'content','layout':layout,'headline':headline,
        'mediaTag':tag,'design':design,'needToSee':'','sourceRole':'illustrative-context'})

c=chapter('opening','Đông khách, nhưng tiền ở đâu?')
beat(c,'h01','Quán kín bàn, máy pha chạy liên tục, đơn hàng cứ nối nhau. Nhưng cuối tháng, chủ quán vẫn phải lấy tiền tiết kiệm để trả tiền thuê. Tiền đã đi đâu?',headline='ĐÔNG KHÁCH. TIỀN ĐI ĐÂU?',tag='busy')
beat(c,'h02','Có thể quán chưa bán đủ. Cũng có thể mỗi đơn bán thêm để lại quá ít, hoặc tiền phải chi đã tới trước tiền thu. Ba chuyện này nhìn ngoài cửa rất giống nhau.','b-split','Một cảnh đông. Ba câu chuyện.',choices=[{'label':'01','title':'Chưa đủ sản lượng'},{'label':'02','title':'Mỗi đơn còn ít'},{'label':'03','title':'Lệch lịch thu–chi'}])
beat(c,'h03','Hôm nay, thử mở một quán cà phê giả định. Ta sẽ lần theo một ly ba mươi lăm nghìn, đi qua tiền thuê, khuyến mại, rồi đến ngày phải trả hóa đơn.','b-coffee','Lần theo một ly 35.000đ',coffee={'kind':'cup'},tag='coffee')
beat(c,'d01','Đây là ví dụ giáo dục về kinh doanh, không phải tư vấn tài chính cho một quán cụ thể. Toàn bộ giá và chi phí đều giả định; thuế, lãi vay và khấu hao chưa được đưa vào mô hình.','b-question','MIỄN TRỪ TRÁCH NHIỆM',theme='cream',emphasis=['Ví dụ giả định','Không phải tư vấn riêng'])
c['beats'][0]['phase']='hook';c['beats'][1]['phase']='hook';c['beats'][2]['phase']='hook';c['beats'][3]['phase']='disclaimer'

c=chapter('one-cup','Một ly bán ra, bao nhiêu tiền ở lại?')
beat(c,'u01','Bắt đầu ở quầy. Một khách trả ba mươi lăm nghìn cho một ly. Số tiền đó là doanh thu, chưa phải phần chủ quán có thể mang về.','b-photo','35.000đ khách trả ≠ tiền mang về',tag='payment')
beat(c,'u02','Để làm thêm một ly, quán cần nguyên liệu, cốc hoặc nắp dùng một lần, và những khoản thay đổi theo đơn bán. Trong ví dụ này, gom chúng thành mười lăm nghìn.','b-photo','Mỗi ly có chi phí đi cùng',tag='ingredients')
beat(c,'u03','Lấy ba mươi lăm trừ mười lăm, còn hai mươi nghìn. Khoản còn lại này góp vào việc trả chi phí cố định và, nếu đủ, tạo ra kết quả dương.','b-paper','Một ly đóng góp bao nhiêu?',paper={'title':'MỘT LY / VÍ DỤ GIẢ ĐỊNH','rows':[{'label':'Giá bán','value':'35.000đ'},{'label':'Biến phí mỗi ly','value':'−15.000đ'}],'total':{'label':'Phần đóng góp','value':'20.000đ'}})
beat(c,'u04','Hai mươi nghìn ấy chưa phải lợi nhuận ròng của ly cà phê. Tiền thuê nhà, nhân sự và nhiều khoản vận hành vẫn đang chờ được trả từ phần đóng góp của cả tháng.','b-coffee','20.000đ chưa phải lợi nhuận ròng',coffee={'kind':'cost'},tag='coffee')
beat(c,'u05','Phân loại chi phí cũng cần theo thực tế. Nhân viên có thể nhận lương tháng, nhưng làm thêm giờ lại tăng theo lượng việc. Điện nước có phần nền và phần tăng theo sử dụng.','b-split','Chi phí có thể pha trộn',choices=[{'label':'PHẦN NỀN','title':'Lương theo tháng','body':'Trong phạm vi công suất đang xét'},{'label':'PHẦN TĂNG','title':'Làm thêm giờ','body':'Thay đổi khi lượng việc tăng'}],tag='staff')
beat(c,'u06','Vì vậy, đừng bê một bảng mẫu sang mọi quán. Ở đây, ta tạm giữ mười lăm nghìn mỗi ly và một mức chi phí cố định, trong phạm vi công suất hiện có.','b-photo','Một mô hình có phạm vi',tag='barista')
beat(c,'u07','Một ly tại chỗ và một ly qua kênh giao hàng cũng có thể để lại số tiền khác nhau. Nếu có phí nền tảng, bao bì hoặc trợ giá, phải tính theo phần quán thực chịu.','b-photo','Cùng món, khác kênh bán',tag='takeaway')
beat(c,'u08','Điều cần hỏi không chỉ là món nào bán chạy. Còn phải hỏi sau những chi phí đi cùng nó, món đó để lại bao nhiêu tiền để nuôi phần còn lại của quán.','b-question','Bán chạy — còn lại bao nhiêu?',theme='dark',tag='coffee')
beat(c,'u09','Một món bán nhiều vẫn có thể góp rất tốt. Nhưng hình ảnh đơn hàng chạy liên tục không tự nói cho ta biết phần đóng góp ấy; cần nhìn vào giá bán thực thu và chi phí.','b-photo','Số đơn chỉ là một phần',tag='busy')

c=chapter('breakeven','Cánh cửa hòa vốn')
beat(c,'b01','Bây giờ đến các khoản theo tháng. Giả sử tiền thuê là mười tám triệu, nhân sự là hai mươi hai triệu, và nhóm chi phí nền khác là tám triệu.','b-paper','Ba khoản đang chờ trả',paper={'title':'CHI PHÍ CỐ ĐỊNH / THÁNG','rows':[{'label':'Thuê mặt bằng','value':'18 triệu'},{'label':'Nhân sự','value':'22 triệu'},{'label':'Chi phí nền khác','value':'8 triệu'}],'total':{'label':'Tổng giả định','value':'48 triệu'}})
beat(c,'b02','Tổng cộng bốn mươi tám triệu. Đây là giả định để tính, không phải mức chi phí chuẩn của ngành cà phê. Một quán thật có thể khác rất xa.','b-photo','48 triệu/tháng — số giả định',tag='storefront')
beat(c,'b03','Mỗi ly đóng góp hai mươi nghìn, vậy cần bao nhiêu ly mới bù được bốn mươi tám triệu? Chia ra, ta được hai nghìn bốn trăm ly trong tháng.','b-chart','Cần 2.400 ly để bù 48 triệu',chart={'kind':'bars','items':[{'label':'Phần đóng góp cần có','value':48}],'unit':'triệu đồng','max':60,'target':48})
beat(c,'b04','Nếu mở đủ ba mươi ngày, đó là bình quân tám mươi ly mỗi ngày. Mốc này mới bù các chi phí đã đưa vào mô hình, chưa bảo đảm chủ quán đạt thu nhập mong muốn.','b-coffee','2.400 ly ÷ 30 ngày = 80 ly/ngày',coffee={'kind':'flow'},tag='coffee')
beat(c,'b05','Dưới mốc đó, phần đóng góp chưa đủ. Trên mốc đó, mô hình bắt đầu có dư. Đường hòa vốn giúp biến câu hỏi có vẻ cảm tính thành một giả thuyết có thể kiểm.','b-chart','Từ sản lượng đến phần đóng góp',chart={'kind':'breakeven','items':[{'label':'40','x':40,'value':24},{'label':'80','x':80,'value':48},{'label':'120','x':120,'value':72}],'fixed':48,'max':80,'unit':'triệu đồng/tháng','xLabel':'Ly/ngày · 30 ngày','highlight':1})
beat(c,'b06','Giả sử quán bán một trăm ly mỗi ngày. Ba nghìn ly trong tháng tạo một trăm lẻ năm triệu doanh thu. Trừ bốn mươi lăm triệu biến phí, phần đóng góp là sáu mươi triệu.','b-paper','100 ly/ngày trong mô hình',paper={'title':'3.000 LY / 30 NGÀY','rows':[{'label':'Doanh thu','value':'105 triệu'},{'label':'Biến phí','value':'−45 triệu'}],'total':{'label':'Phần đóng góp','value':'60 triệu'}})
beat(c,'b07','Trả tiếp bốn mươi tám triệu chi phí cố định, còn mười hai triệu. Cần gọi đúng: đây là phần dư của mô hình trước thuế, lãi vay và khấu hao, không phải lợi nhuận ròng đã chốt.','b-chart','105 − 45 − 48 = 12 triệu',chart={'kind':'waterfall','items':[{'label':'Doanh thu','value':105},{'label':'Biến phí','value':-45},{'label':'Cố định','value':-48},{'label':'Còn lại*','value':12}],'unit':'triệu đồng','max':120})
beat(c,'b08','Còn nếu người chủ chưa tính công của chính mình, bức tranh về thu nhập lại khác. Một mô hình hữu ích phải nói rõ đã tính những khoản nào, thay vì đặt nhãn có lãi cho đẹp.','b-photo','Đừng quên công sức người chủ',tag='closing')

c=chapter('busy-hours','Một giờ đông không phải cả tháng tốt')
beat(c,'v01','Quay lại cảnh đầu: nhìn qua cửa, bạn thấy kín bàn. Nhưng đó có thể là lúc đông nhất. Phép tính tháng cần tổng đơn của cả ngày, kể cả những giờ yên ắng.','b-photo','Một giờ đông ≠ cả tháng tốt',tag='busyquiet')
beat(c,'v02','Trong quán giả định, sáu mươi ly bán buổi sáng nhưng chỉ thêm mười ly cả phần ngày còn lại, tổng vẫn là bảy mươi. Dưới mốc tám mươi, dù sáng trông rất nhộn nhịp.','b-chart','60 ly sáng + 10 ly còn lại = 70',chart={'kind':'bars','items':[{'label':'Buổi sáng','value':60},{'label':'Còn lại','value':10},{'label':'Cả ngày','value':70}],'max':90,'unit':'ly','target':80})
beat(c,'v03','Ngược lại, một quán không kín chỗ vẫn có thể bán đều qua nhiều khung giờ hoặc nhiều kênh. Không thể đọc toàn bộ sức khỏe kinh doanh chỉ bằng số ghế đang có người ngồi.','b-photo','Ghế có khách chưa kể hết câu chuyện',tag='takeaway')
beat(c,'v04','Bởi vậy, hãy tách điều nhìn thấy khỏi điều cần đo. Khách đông là một quan sát. Số đơn, giá thực thu và phần đóng góp trong cả ngày mới đưa quan sát ấy vào phép tính.','b-split','Nhìn thấy / Cần đo',choices=[{'label':'QUAN SÁT','title':'Có lúc kín bàn'},{'label':'ĐO LƯỜNG','title':'Đơn × phần đóng góp','body':'Theo ngày và kênh bán'}],tag='busy')
beat(c,'v05','Thêm khách cũng có giới hạn công suất. Khi phải tăng ca, thêm thiết bị hoặc chờ lâu hơn, giả định chi phí cũ có thể không còn đúng. Tăng sản lượng cần được tính cùng chi phí mới.','b-photo','Thêm đơn có thể kéo theo thêm chi phí',tag='staff')
beat(c,'v06','Nhưng trước khi quán kịp tăng công suất, một cách kéo khách quen thuộc đã xuất hiện: giảm giá. Trên màn hình, số đơn tăng rất đẹp. Trong phép tính, chuyện gì xảy ra?','b-question','Giảm giá: đông hơn, có tốt hơn?',theme='warm',tag='payment')

c=chapter('discount','Cái bẫy nhìn mỗi số đơn')
beat(c,'p01','Giữ nguyên ly cũ, hạ giá từ ba mươi lăm xuống hai mươi chín nghìn. Nếu biến phí vẫn mười lăm nghìn, mỗi ly giờ chỉ còn đóng góp mười bốn nghìn.','b-paper','35.000đ → 29.000đ',paper={'title':'GIẢ ĐỊNH KHUYẾN MẠI','rows':[{'label':'Giá mới','value':'29.000đ'},{'label':'Biến phí giữ nguyên','value':'−15.000đ'}],'total':{'label':'Phần đóng góp mới','value':'14.000đ'}})
beat(c,'p02','Giá bán giảm sáu nghìn, nhưng phần đóng góp giảm từ hai mươi xuống mười bốn nghìn, tức ba mươi phần trăm. Hai tỷ lệ khác nhau vì chúng có mẫu số khác nhau.','b-chart','Phần đóng góp giảm 30%',chart={'kind':'bars','items':[{'label':'Trước','value':20},{'label':'Sau','value':14}],'unit':'nghìn đồng/ly','max':24,'highlight':1})
beat(c,'p03','Muốn giữ phần đóng góp sáu mươi triệu như tháng bán ba nghìn ly giá cũ, quán phải bán hơn bốn nghìn hai trăm tám mươi lăm ly ở giá mới. Làm tròn lên là bốn nghìn hai trăm tám mươi sáu.','b-paper','Giữ 60 triệu cần 4.286 ly',paper={'title':'CÙNG MỘT MỤC TIÊU ĐÓNG GÓP','rows':[{'label':'Mục tiêu','value':'60.000.000đ'},{'label':'Mỗi ly giá mới','value':'14.000đ'}],'total':{'label':'Số ly làm tròn lên','value':'4.286 ly'}})
beat(c,'p04','Tức cần tăng khoảng bốn mươi ba phần trăm sản lượng, chỉ để giữ nguyên mức đóng góp cũ. Chưa tính thêm nhân lực, nguyên liệu thất thoát hoặc những khoản khuyến mại quán phải gánh khác.','b-chart','Cần khoảng 43% ly nhiều hơn',chart={'kind':'bars','items':[{'label':'Giá cũ','value':3000},{'label':'Giá mới','value':4286}],'max':5000,'unit':'ly/tháng','highlight':1})
beat(c,'p05','Ngay cả mốc hòa vốn cũng đổi. Bốn mươi tám triệu chia mười bốn nghìn cần làm tròn lên ba nghìn bốn trăm hai mươi chín ly mỗi tháng, xấp xỉ một trăm mười lăm ly mỗi ngày.','b-paper','Hòa vốn mới: khoảng 115 ly/ngày',paper={'title':'CÙNG 48 TRIỆU CHI PHÍ CỐ ĐỊNH','rows':[{'label':'Phần đóng góp mới','value':'14.000đ/ly'},{'label':'Số ly/tháng làm tròn lên','value':'3.429 ly'}],'total':{'label':'Bình quân 30 ngày','value':'≈115 ly/ngày'}})
beat(c,'p06','Điều đó không có nghĩa khuyến mại luôn sai. Một chương trình có thể thu hút khách thử hoặc phục vụ mục tiêu khác. Nhưng mục tiêu, chi phí và cách kiểm tra phải được nói rõ từ đầu.','b-photo','Khuyến mại cần một mục tiêu rõ',tag='serve')
beat(c,'p07','Nếu muốn biết khách có quay lại hay không, cần theo dõi hành vi quay lại. Nếu muốn tăng phần đóng góp, cần đo phần đóng góp. Lượt xem, số đơn và tiền còn lại là những thước đo khác nhau.','b-split','Đo đúng mục tiêu',choices=[{'label':'THỬ SẢN PHẨM','title':'Khách có quay lại?'},{'label':'KINH TẾ ĐƠN HÀNG','title':'Đóng góp có tăng?'}],tag='phone')
beat(c,'p08','Và đừng so ngày khuyến mại với một ngày vắng bất thường rồi kết luận thành công. Thời tiết, ngày trong tuần và sự kiện quanh quán có thể thay đổi lượng khách. Mẫu so cần đủ bối cảnh.','b-photo','So sánh có cùng bối cảnh',tag='busyquiet')
beat(c,'p09','Cái bẫy ở đây là một con số đẹp che một con số quan trọng hơn. Quán bán thêm không tự bảo đảm quán khỏe thêm. Còn một lớp dễ bị bỏ quên: lịch tiền mặt.','b-question','Nhiều đơn hơn. Tiền có kịp về?',theme='dark')

c=chapter('cash','Có dư trên giấy, vẫn thiếu tiền mặt')
beat(c,'m01','Giả sử quán thật sự có phần dư mười hai triệu theo mô hình. Vậy tài khoản cuối tháng phải tăng đúng mười hai triệu sao? Không nhất thiết, vì kết quả kinh doanh và tiền mặt không cùng một câu hỏi.','b-question','12 triệu phần dư ≠ tài khoản +12 triệu',theme='cream')
beat(c,'m02','Một bên hỏi doanh thu và chi phí thuộc kỳ này là bao nhiêu. Bên kia hỏi trong kỳ, tiền thực đã đi vào và đi ra lúc nào. Khoảng cách về thời điểm có thể làm quán hụt hơi.','b-split','Kết quả / Thời điểm',choices=[{'label':'KẾT QUẢ','title':'Thuộc kỳ nào?'},{'label':'TIỀN MẶT','title':'Thu, chi ngày nào?'}])
beat(c,'m03','Chẳng hạn, mua nguyên liệu đủ dùng nhiều tuần khiến tiền ra ngay, trong khi một phần hàng vẫn còn trong kho. Không thể cứ nhìn khoản chuyển tiền mua hàng rồi gọi toàn bộ là chi phí của số ly đã bán.','b-photo','Tiền ra mua hàng / Hàng còn trong kho',tag='beans')
beat(c,'m04','Đặt cọc mặt bằng cũng cần được tách riêng. Đó là tiền đã rời tài khoản và bị giữ theo thỏa thuận, nhưng không đơn giản là tiền thuê đã tiêu hết của tháng này.','b-paper','Cọc thuê và tiền thuê là hai khoản',paper={'title':'PHÂN LOẠI TRƯỚC KHI CỘNG','rows':[{'label':'Tiền thuê của tháng','value':'Chi phí theo kỳ'},{'label':'Tiền đặt cọc','value':'Tiền bị giữ theo hợp đồng'}]},tag='storefront')
beat(c,'m05','Tương tự, mua một máy pha là khoản chi tiền cho tài sản. Cách ghi nhận chi phí theo thời gian khác việc trả tiền ngay; mô hình đơn giản ban đầu của ta chưa xử lý khấu hao ấy.','b-photo','Mua máy: tiền ra ngay',tag='machine')
beat(c,'m06','Ngay cả tiền bán hàng cũng có lịch. Khách có thể trả tại quầy, hoặc một kênh bán đối soát và chuyển về sau. Lịch thực tế tùy thỏa thuận, không nên tự coi mọi doanh thu là tiền sẵn dùng.','b-photo','Doanh thu chưa chắc đã sẵn dùng',tag='payment')
beat(c,'m07','Thử một tình huống riêng: đầu tuần có hai mươi triệu, trong tuần thu mười lăm triệu, nhưng các khoản đến hạn cần bốn mươi triệu. Thiếu năm triệu trước khi bàn tới mục tiêu tăng trưởng.','b-chart','20 + 15 − 40 = thiếu 5 triệu',chart={'kind':'waterfall','items':[{'label':'Đầu tuần','value':20},{'label':'Thu trong tuần','value':15},{'label':'Khoản đến hạn','value':-40},{'label':'Còn thiếu','value':-5}],'unit':'triệu đồng','max':45})
beat(c,'m08','Đây là ví dụ về lịch thu chi, không phải phần tiếp của phép tính tháng trước. Một quán có thể cần giải quyết cả mức đóng góp lẫn thời điểm tiền về; sửa mỗi lượng khách chưa chắc sửa được hai việc đó.','b-question','Hai phép tính. Hai câu hỏi.',theme='dark')
beat(c,'m09','Một tờ lịch tiền mặt có thể rất ngắn: số dư đầu kỳ, tiền dự kiến thu, khoản phải chi và ngày đến hạn. Ghi thêm điều kiện nào chưa chắc chắn, để không biến dự báo thành lời hứa.','b-paper','Lịch tiền mặt ngắn, nhưng đủ câu hỏi',paper={'title':'TUẦN TỚI','rows':[{'label':'Bắt đầu với bao nhiêu?','value':'Số dư'},{'label':'Thu khoản nào, ngày nào?','value':'Dự kiến thu'},{'label':'Chi khoản nào, hạn nào?','value':'Đến hạn'}],'total':{'label':'Cuối kỳ dự kiến','value':'Cần đối chiếu'}})

c=chapter('one-week','Một tuần để nhìn rõ quán')
beat(c,'a01','Nếu đang kinh doanh, không nhất thiết bắt đầu bằng một bảng tính hàng trăm dòng. Có thể bắt đầu bằng một tuần quan sát có chủ đích, rồi đối chiếu với sổ sách và người phụ trách kế toán.','b-photo','Một tuần nhìn kỹ hơn',tag='closing')
beat(c,'a02','Ngày đầu, chọn vài món và kênh bán chính. Ghi giá thực thu, chi phí trực tiếp mỗi đơn và những khoản quán tự trợ. Đừng lấy giá trên thực đơn thay cho số tiền thực giữ lại.','b-paper','1 / Đọc từng đơn hàng',paper={'title':'ĐƠN HÀNG THỰC TẾ','rows':[{'label':'Giá thực thu','value':'Sau điều chỉnh'},{'label':'Chi phí đi cùng','value':'Theo món và kênh'}],'total':{'label':'Phần đóng góp','value':'Cần tính lại'}})
beat(c,'a03','Ngày tiếp theo, liệt kê các khoản theo tháng và chỉ ra khoản nào thay đổi khi bán nhiều hơn. Nhớ tách công của người chủ, khoản đầu tư ban đầu và tiền cọc khỏi những con số dễ nhầm.','b-photo','2 / Nhìn đủ chi phí',tag='staff')
beat(c,'a04','Trong những ngày sau, ghi lượng đơn theo khung giờ. Một vài buổi đông không thay được dữ liệu cả tuần, và một tuần cũng chưa đủ đại diện cho cả năm.','b-photo','3 / Ghi cả giờ đông lẫn giờ vắng',tag='busyquiet')
beat(c,'a05','Khi thử một thay đổi, hãy chọn câu hỏi cụ thể. Chẳng hạn, sửa cách giới thiệu một món để xem phần đóng góp thay đổi thế nào, đồng thời theo dõi chất lượng phục vụ và phản hồi của khách.','b-photo','4 / Một thay đổi, một câu hỏi',tag='serve')
beat(c,'a06','Tránh đổi giá, quảng cáo, lịch nhân sự và thực đơn cùng một lúc rồi khó biết điều gì tạo ra khác biệt. Dữ liệu nhỏ vẫn hữu ích nếu ta giữ được cách so sánh và ghi nhận giới hạn.','b-split','Giữ phép so có ý nghĩa',choices=[{'label':'TRƯỚC','title':'Một cách vận hành'},{'label':'SAU','title':'Một thay đổi rõ','body':'Ghi điều kiện đi cùng'}])
beat(c,'a07','Cuối tuần, xem ba thứ cạnh nhau: phần đóng góp mỗi đơn, lượng đơn theo thời gian, và lịch tiền mặt sắp tới. Khi chúng lệch nhau, ta mới biết cần đào sâu vào đâu.','b-paper','Ba dòng trước khi kết luận',paper={'title':'CÙNG NHÌN MỘT QUÁN','rows':[{'label':'Mỗi đơn để lại','value':'Bao nhiêu?'},{'label':'Cả ngày bán được','value':'Bao nhiêu?'},{'label':'Tiền về và đi','value':'Ngày nào?'}]})
beat(c,'a08','Nếu chi phí tăng theo công suất hoặc quán bán nhiều loại món, mô hình một ly cần được mở rộng. Dùng số liệu thực và người có chuyên môn để xem lại, thay vì cố nhét mọi thứ vào ví dụ này.','b-photo','Mô hình đơn giản cần được mở rộng',tag='barista')

c=chapter('ending','Trở lại cánh cửa quán')
beat(c,'e01','Giờ nhìn lại quán kín bàn lúc đầu. Ta không còn vội kết luận quán ấy đang rất có lãi, cũng không vội bảo họ kinh doanh kém nếu đang thiếu tiền.','b-photo','Nhìn lại cùng một cảnh',tag='busy')
beat(c,'e02','Ta hỏi mỗi đơn góp bao nhiêu, cần bán bao nhiêu để nuôi bộ máy, và tiền có kịp về trước ngày phải trả. Ba câu hỏi bình thường, nhưng mở ra ba cách chẩn đoán khác nhau.','b-coffee','Mỗi đơn · Cả tháng · Ngày đến hạn',coffee={'kind':'flow'},tag='coffee')
beat(c,'e03','Một quán bền vững cần cả khách hàng lẫn một mô hình kinh tế phù hợp. Chất lượng đồ uống, trải nghiệm và con người vẫn quan trọng; phép tính giúp nhìn rõ điều kiện để duy trì chúng.','b-photo','Con số để duy trì điều đáng giữ',tag='serve')
beat(c,'e04','Nếu nhớ một điều, hãy nhớ: doanh thu cho biết tiền bán được, phần đóng góp giúp trả chi phí, còn dòng tiền cho biết khả năng xoay xở theo lịch. Chúng liên quan, nhưng không thể dùng thay nhau.','b-question','Doanh thu · Phần đóng góp · Dòng tiền',theme='warm')
beat(c,'e05','Bạn muốn thử bóc tách mô hình của tiệm bánh, cửa hàng nhỏ hay một dịch vụ khác? Chia sẻ ở bình luận và theo dõi để cùng nhìn kỹ hơn cách những doanh nghiệp quanh ta vận hành.','b-closing','Bạn muốn bóc tách mô hình nào tiếp?',tag='closing')
for s in c['beats']:s['phase']='cta' if s['id']=='e05' else 'content'

for c in chapters:
    c['text']=' '.join(b['text'] for b in c['beats'])
    c['wordCount']=len(c['text'].split())
